"""Generates the human-readable DATABASE.md export from the SQLite catalog."""

from app import dedup


def _fmt_size(n: int | None) -> str:
    if not n:
        return "-"
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024:
            return f"{n:.0f}{unit}" if unit == "B" else f"{n:.1f}{unit}"
        n /= 1024
    return f"{n:.1f}TB"


def write_database_md(rows: list, cat_map: dict, out_path: str) -> None:
    by_name = dedup.group_by_name(rows)

    lines = [
        "# Plugin Database",
        "",
        "Generated by `app/scanner.py` — do not hand-edit, re-run the scan instead.",
        "See [AGENTS.md](AGENTS.md) for format priority (CLAP > VST3 > VST2), status meanings, and roadmap.",
        "",
        "Note: \"superseded by\" only fires when the candidate formats also agree on vendor "
        "(or both have no known vendor) — same-named plugins from different vendors are never "
        "auto-grouped.",
        "",
        "Categories marked *(heuristic)* are keyword-guessed from the plugin name (`app/categorizer.py`), "
        "not vendor-authoritative — treat as a suggestion.",
        "",
        "| Name | Vendor | Version | Format | Type | Categories | Path | Size | Status |",
        "|---|---|---|---|---|---|---|---|---|",
    ]

    for r in rows:
        siblings = dedup.siblings_of(r, by_name)
        format_cell = r["format"]
        if len(siblings) > 1:
            best = max(siblings, key=dedup.priority)
            if dedup.priority(best) > dedup.priority(r):
                format_cell += f" (superseded — {dedup.reason(r, best)})"

        status_cell = r["status"]
        if r["status_reason"]:
            status_cell += f" — {r['status_reason']}"

        vendor_cell = r["vendor"] or "-"
        if r["vendor"] and r["vendor_source"] == "inferred":
            vendor_cell += " *(inferred)*"

        tags = cat_map.get(r["id"], [])
        if tags:
            cat_cell = ", ".join(f"{name}*" if source == "heuristic" else name for name, slug, source in tags)
        else:
            cat_cell = "-"

        lines.append(
            "| {name} | {vendor} | {version} | {format} | {type} | {cats} | `{path}` | {size} | {status} |".format(
                name=r["name"] or "-",
                vendor=vendor_cell,
                version=r["version"] or "-",
                format=format_cell,
                type=r["plugin_type"] or "-",
                cats=cat_cell,
                path=r["host_path"],
                size=_fmt_size(r["size_bytes"]),
                status=status_cell,
            )
        )

    flagged = [r for r in rows if r["status"] != "ok"]
    if flagged:
        lines += ["", "## Flagged for review", ""]
        for r in flagged:
            lines.append(f"- **{r['name']}** (`{r['host_path']}`) — {r['status']}: {r['status_reason']}")

    inferred = [r for r in rows if r["vendor_source"] == "inferred"]
    if inferred:
        lines += ["", "## Vendor identified by research, not by the file itself", "",
                   "These vendors came from a manual web/installer-archive research pass "
                   "(`app/enrichment.py`), not from the plugin's own metadata — double check if it matters.", ""]
        for r in inferred:
            lines.append(f"- **{r['name']}** → {r['vendor']}: {r['vendor_note']}")

    ambiguous = [r for r in rows if not r["vendor"] and r["vendor_note"]]
    if ambiguous:
        lines += ["", "## Vendor could not be determined — needs manual check", "",
                   "Two or more real plugins share this exact name; picking one would be a guess. "
                   "Open the plugin in your DAW to see which is actually installed.", ""]
        for r in ambiguous:
            lines.append(f"- **{r['name']}** (`{r['host_path']}`): {r['vendor_note']}")

    with open(out_path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
